```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("produkty.txt");
    vector<pair<string, int>> produkty;
    string nazwa;
    int cena;
    int suma = 0;
    while (plik >> nazwa >> cena) {
        produkty.push_back({nazwa, cena});
        suma += cena;
    }
    double srednia = (double)suma / produkty.size();

    cout << "a) Srednia cena: " << fixed << setprecision(2) << srednia << endl;

    cout << endl << "b) Produkty >= sredniej:" << endl;
    for (auto &p : produkty) {
        if (p.second >= srednia) {
            cout << "   " << p.first << ": " << p.second << endl;
        }
    }
    return 0;
}
```

Weryfikacja:
- Suma cen: 5+4+25+32+6+12+45+15 = 144
- Srednia: 144/8 = 18.00
- Produkty >= 18.00: Ser(25), Szynka(32), Kawa(45)
